using Microsoft.EntityFrameworkCore; using SmartCampusServicePortal.Models; namespace SmartCampusServicePortal.Data; public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> o):DbContext(o){public DbSet<Student> Students=>Set<Student>(); public DbSet<ServiceRequest> ServiceRequests=>Set<ServiceRequest>(); protected override void OnModelCreating(ModelBuilder b){b.Entity<Student>().HasIndex(x=>x.StudentIdNumber).IsUnique();}}